INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 2, FALSE, '["abcd"]', '"abcd"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 3, FALSE, '["zzzzzzzzzzzz"]', '"z12"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 4, TRUE, '["a"]', '"a"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 5, TRUE, '["aa"]', '"a2"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 6, TRUE, '["abbbbbbbbbba"]', '"ab10a"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 7, TRUE, '["aabbaa"]', '"a2b2a2"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 8, TRUE, '[""]', '""');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 9, TRUE, '[""]', '"a300"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 10, TRUE, '[""]', '"q999r"');
INSERT INTO test_cases (problem_id, sequence, hidden, input, expected) VALUES (2, 11, TRUE, '[""]', '""');

INSERT INTO problems (id, title, level, description, return_type, time_limit_ms, memory_limit_mb) VALUES (3, '액자 테두리의 합', 1, '## 문제 설명
정수가 적힌 2차원 배열 `grid`를 액자라고 생각합니다. 액자의 테두리, 즉 첫 행·마지막 행·첫 열·마지막 열에 있는 칸의 합을 return 하도록 solution 함수를 완성해주세요.
한 칸이 여러 테두리에 동시에 속하더라도 한 번만 더합니다.

## 제한사항
- 1 ≤ `grid`의 행 길이, 열 길이 ≤ 100
- 모든 행의 길이는 같습니다.
- -1,000,000,000 ≤ `grid`의 원소 ≤ 1,000,000,000

## 입출력 예
| grid | result |
|---|---|
| [[1, 2, 3], [4, 5, 6], [7, 8, 9]] | 40 |
| [[5]] | 5 |
| [[1, 2], [3, 4]] | 10 |

## 입출력 예 설명
- 입출력 예 #1: 가운데 5를 제외한 모든 칸이 테두리이므로 1+2+3+4+6+7+8+9 = 40 입니다.
- 입출력 예 #2: 칸이 하나뿐이므로 그 칸이 곧 테두리입니다.
', 'long', DEFAULT, DEFAULT);
